import React, { useState } from 'react';
import '../styles/theme.css';

export default function Payment() {
  const [payType, setPayType] = useState('received');
  const [formData, setFormData] = useState({
    party: 'Ramesh Patel',
    amount: '50000',
    mode: 'Bank Transfer',
    reference: 'UTR123456789',
    notes: 'Advance payment for wheat purchase'
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  return (
    <div style={{ padding: '20px', maxWidth: '480px', margin: '0 auto', fontFamily: 'Segoe UI, sans-serif' }}>
      
      {/* Header */}
      <h2 style={{ color: '#1B4D3E', marginBottom: '20px' }}>Record Payment</h2>

      {/* Received / Paid Toggle */}
      <div style={{ display: 'flex', background: '#EAE5D9', padding: '4px', borderRadius: '8px', marginBottom: '20px' }}>
        <button 
          onClick={() => setPayType('received')} 
          style={{ flex: 1, padding: '10px', border: 'none', borderRadius: '6px', background: payType === 'received' ? '#1B4D3E' : 'transparent', color: payType === 'received' ? '#FFF' : '#666', fontWeight: 'bold', cursor: 'pointer' }}>
          Payment Received
        </button>
        <button 
          onClick={() => setPayType('paid')} 
          style={{ flex: 1, padding: '10px', border: 'none', borderRadius: '6px', background: payType === 'paid' ? '#C0392B' : 'transparent', color: payType === 'paid' ? '#FFF' : '#666', fontWeight: 'bold', cursor: 'pointer' }}>
          Payment Paid
        </button>
      </div>

      <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        
        {/* Party / Farmer Name */}
        <div>
          <label style={labelStyle}>Party / Farmer Name</label>
          <input type="text" name="party" value={formData.party} onChange={handleChange} style={inputStyle} />
        </div>

        {/* Amount */}
        <div>
          <label style={labelStyle}>Amount (₹)</label>
          <input type="number" name="amount" value={formData.amount} onChange={handleChange} style={{ ...inputStyle, fontSize: '18px', fontWeight: 'bold', color: payType === 'received' ? '#27AE60' : '#C0392B' }} />
        </div>

        {/* Payment Mode */}
        <div>
          <label style={labelStyle}>Payment Mode</label>
          <select name="mode" value={formData.mode} onChange={handleChange} style={inputStyle}>
            <option value="Bank Transfer">Bank Transfer (NEFT/RTGS/IMPS)</option>
            <option value="UPI">UPI (Google Pay / PhonePe)</option>
            <option value="Cash">Cash</option>
            <option value="Cheque">Cheque</option>
          </select>
        </div>

        {/* Reference Number */}
        <div>
          <label style={labelStyle}>Reference / UTR No.</label>
          <input type="text" name="reference" value={formData.reference} onChange={handleChange} style={inputStyle} />
        </div>

        {/* Notes */}
        <div>
          <label style={labelStyle}>Notes / Remarks</label>
          <textarea name="notes" rows="2" value={formData.notes} onChange={handleChange} style={{ ...inputStyle, resize: 'none' }} />
        </div>

      </form>

      {/* Submit Button */}
      <button style={{ width: '100%', background: payType === 'received' ? '#1B4D3E' : '#C0392B', color: '#FFF', padding: '14px', border: 'none', borderRadius: '12px', fontWeight: 'bold', fontSize: '16px', marginTop: '25px', cursor: 'pointer', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' }}>
        Save {payType === 'received' ? 'Received' : 'Paid'} Entry
      </button>

    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '12px', fontWeight: '600', color: '#555', marginBottom: '6px' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #EAE5D9', background: '#FFF', fontSize: '14px', boxSizing: 'border-box' };then
